import { Component, forwardRef, input, signal } from '@angular/core';
import {
    ControlValueAccessor,
    FormsModule,
    NG_VALUE_ACCESSOR,
} from '@angular/forms';

import { MatRippleModule } from '@angular/material/core';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { AsyncHandler } from '../../common/async-handler.class';
import { HashMap } from '../../common/types';
import { IconComponent } from '../icon.component';
import { TranslatePipe } from '../translate.pipe';

@Component({
    selector: 'object-list-field',
    template: `
        @if (fields() && fields().length) {
            <div class="object-list">
                @if (active_list().length) {
                    <div class="header row h-6 text-sm">
                        @for (field of fields(); track field) {
                            <div class="field capitalize" [attr.name]="field">
                                {{ field }}
                            </div>
                        }
                        <div class="w-10"></div>
                    </div>
                }
                @for (item of active_list(); track item) {
                    <div class="row">
                        @for (field of fields(); track field) {
                            <div class="field" [attr.name]="field">
                                <mat-form-field appearance="outline">
                                    <input
                                        matInput
                                        [name]="field"
                                        [placeholder]="field"
                                        [disabled]="disabled()"
                                        [(ngModel)]="item[field]"
                                        (ngModelChange)="
                                            setValue(active_list())
                                        "
                                    />
                                </mat-form-field>
                            </div>
                        }
                        <button
                            icon
                            matRipple
                            class="border-error text-error h-12 w-12 rounded-sm border"
                            [disabled]="disabled()"
                            (click)="removeRow(item)"
                        >
                            <icon>delete</icon>
                        </button>
                    </div>
                }
                <div class="row h-10 text-center">
                    <button
                        btn
                        type="button"
                        class="w-full"
                        [disabled]="disabled()"
                        (click)="addRow()"
                    >
                        <div class="contents">
                            <icon class="text-2xl">add</icon>
                            <div class="text">
                                {{ 'COMMON.NEW_ITEM' | translate }}
                            </div>
                        </div>
                    </button>
                </div>
            </div>
        }
    `,
    styles: [
        `
            :host,
            mat-form-field {
                width: 100%;
            }

            .row {
                display: flex;
                width: 100%;
                height: 3.5em;
            }

            .row > * {
                margin: 0 0.25em;
            }

            .row > *:first-child {
                margin-left: 0;
            }

            .row > *:last-child {
                margin-right: 0;
            }

            .header > * {
                padding: 0 0.5em;
            }

            .field {
                flex: 1;
                min-width: 1px;
            }

            button .contents {
                display: flex;
                align-items: center;
            }
        `,
    ],
    providers: [
        {
            provide: NG_VALUE_ACCESSOR,
            useExisting: forwardRef(() => ObjectListFieldComponent),
            multi: true,
        },
    ],
    imports: [
        IconComponent,
        TranslatePipe,
        MatRippleModule,
        FormsModule,
        MatFormFieldModule,
        MatInputModule,
    ],
})
export class ObjectListFieldComponent
    extends AsyncHandler
    implements ControlValueAccessor
{
    /** List of fields that can be populated for each object */
    public readonly fields = input<string[]>(undefined);
    public readonly disabled = signal(false);
    /** List of objects */
    public readonly active_list = signal<HashMap[]>([]);

    /** Form control on change handler */
    private _onChange: (_: HashMap[]) => void;
    /** Form control on touch handler */
    private _onTouch: (_: HashMap[]) => void;

    /** Add a new item the the active list */
    public addRow() {
        if (this.disabled()) return;
        this.active_list.update((list) => [...list, {}]);
        this.setValue(this.active_list());
    }

    /**
     * Remove item from the active list
     * @param item Item to remove
     */
    public removeRow(item: HashMap) {
        if (this.disabled()) return;
        const index = this.active_list().indexOf(item);
        if (index >= 0) {
            this.active_list.update((list) =>
                list.filter((_, item_index) => item_index !== index),
            );
        }
        this.setValue(this.active_list());
    }

    /**
     * Update the form field value
     * @param new_value New value to set on the form field
     */
    public setValue(new_value: HashMap[]): void {
        if (this.disabled()) return;
        if (this._onChange) {
            this._onChange(new_value);
        }
        this._onTouch?.(new_value);
    }

    /**
     * Update local value when form control value is changed
     * @param value The new value for the component
     */
    public writeValue(value: HashMap[]) {
        this.active_list.set(value || []);
    }

    /**
     * Registers a callback function that is called when the
     * control's value changes in the UI.
     * @param fn The callback function to register
     */
    public registerOnChange(fn: (_: HashMap[]) => void): void {
        this._onChange = fn;
    }

    /**
     * Registers a callback function is called by the forms
     * API on initialization to update the form model on blur.
     * @param fn The callback function to register
     */
    public registerOnTouched(fn: (_: HashMap[]) => void): void {
        this._onTouch = fn;
    }

    public setDisabledState(disabled: boolean) {
        this.disabled.set(disabled);
    }
}
